SEP = ","
QUOTE = "\""


def parse_fields(text):
    """Parse a line like name=Ann, note="hi, there" into a dict of strings.

    Fields are separated by SEP. Whitespace around keys and around unquoted values is
    ignored. A value may be wrapped in QUOTE characters; inside quotes, SEP and '='
    are ordinary characters, whitespace is kept, and two QUOTE characters in a row
    stand for one QUOTE character. Empty fields, such as one after a trailing SEP,
    are skipped, so a blank line gives {}. A field without '=', an empty key, a
    quote that is never closed, or a key that appears twice raises ValueError.
    """
    result = {}
    n = len(text)
    i = 0
    while i < n:
        # read key up to '=' (or SEP / end)
        j = i
        while j < n and text[j] != "=" and text[j] != SEP:
            j += 1
        raw_key = text[i:j]
        if j >= n or text[j] == SEP:
            if raw_key.strip():
                raise ValueError(f"field without '=': {raw_key!r}")
            i = j + 1
            continue
        key = raw_key.strip()
        if not key:
            raise ValueError("empty key")
        j += 1  # skip '='
        k = j
        while k < n and text[k] in " \t\r\n\f\v":
            k += 1
        if k < n and text[k] == QUOTE:
            k += 1
            value = ""
            while True:
                if k >= n:
                    raise ValueError("unclosed quote")
                if text[k] == QUOTE:
                    if k + 1 < n and text[k + 1] == QUOTE:
                        value += QUOTE
                        k += 2
                        continue
                    k += 1
                    break
                value += text[k]
                k += 1
            while k < n and text[k] != SEP:
                if not text[k].isspace():
                    raise ValueError("text after closing quote")
                k += 1
            i = k + 1
        else:
            e = k
            while e < n and text[e] != SEP:
                e += 1
            value = text[k:e].strip()
            i = e + 1
        if key in result:
            raise ValueError(f"duplicate key {key!r}")
        result[key] = value
    return result
